noisy_circuit = stim.Circuit()
for instruction in test_circuit:
  if instruction.name in ["CX", "CZ"]:
    noisy_circuit.append(instruction)
    noisy_circuit.append("DEPOLARIZE2", instruction.targets_copy(), 0.0001)
  elif instruction.name in ["M", "MX"]:
    noisy_circuit.append(instruction.name, instruction.targets_copy(), 0.0001)
  elif instruction.name in ["R", "RX", "H"]:
    noisy_circuit.append(instruction)
    noisy_circuit.append("DEPOLARIZE1", instruction.targets_copy(), 0.0001)
  elif instruction.name in ["QUBIT_COORDS", "DETECTOR", "TICK", "OBSERVABLE_INCLUDE", "DEPOLARIZE1", "DEPOLARIZE2"]:
    noisy_circuit.append(instruction)
  else:
    raise NotImplementedError("forgot " + str(instruction))
  
print(len(noisy_circuit.shortest_graphlike_error())) 
